1	/****************************************************************************
2	 * Contest 2026 team 008 - soldering iron module
3	 *
4	 * MAX6675 K-thermocouple reader over software SPI (bit-bang GPIO),
5	 * software PWM heater control and a simple PID loop.
6	 *
7	 * Wiring (Arduino headers):
8	 *   MAX6675 SCK -> D8  (PE3)
9	 *   MAX6675 CS  -> D7  (PI8)
10	 *   MAX6675 SO  -> D6  (PE6)
11	 *   Heater PWM  -> D3  (PA6) -> NPN transistor -> MOSFET -> 24V iron
12	 *   Sleep sense -> D2  (PG3)
13	 *
14	 * The remaining Arduino pins are owned by other modules:
15	 *   D4 (PK1) / D5 (PA8) -> TCA9548A software I2C, see cs_i2c_sw.c
16	 *   D9 (PH15)           -> board ID input, not used yet
17	 *
18	 * MAX6675 protocol (16-bit read):
19	 *   D15=0(dummy), D14-D3=temp(12bit, 0.25C/bit),
20	 *   D2=1 thermocouple open, D1=0, D0=tri-state
21	 ****************************************************************************/
22	
23	#include <nuttx/config.h>
24	
25	#include <stdio.h>
26	#include <stdint.h>
27	#include <stdbool.h>
28	#include <unistd.h>
29	#include <math.h>
30	#include <syslog.h>
31	
32	#include <nuttx/arch.h>
33	#include <arch/board/board.h>
34	
35	#include "iron.h"
36	
37	/* GPIO config macros come from chip headers not on the app include
38	 * path; use explicit values via the generic stm32 API forward decls.
39	 */
40	extern int  stm32_configgpio(uint32_t cfgset);
41	extern void stm32_gpiowrite(uint32_t pinset, bool value);
42	extern bool stm32_gpioread(uint32_t pinset);
43	
44	/****************************************************************************
45	 * Pre-processor Definitions
46	 ****************************************************************************/
47	
48	/* --- GPIO pin assignments (Arduino D2/D3/D6/D7/D8) ---
49	 * stm32_gpio.h is not on the app include path, so pinsets are built
50	 * from the documented bit layout:
51	 *   MODE bits18-19 (OUTPUT=1<<18), SPEED bits10-11 (50MHz=2<<10),
52	 *   OUTPUT_SET bit8 (0x100), PORT bits4-7 (A=0,E=4,I=8), PIN bits0-3
53	 */
54	#define GPIO_OUTPUT_VAL     (1u << 18)
55	#define GPIO_SPEED_50MHZ    (2u << 10)
56	#define GPIO_OUTPUT_SETBIT  (1u << 8)
57	#define GPIO_PULLUP         (1u << 16)
58	
59	#define IRON_GPIO_SCK    (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
60	                          (4u << 4) | 3u)              /* D8 = PE3  */
61	#define IRON_GPIO_CS     (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
62	                          GPIO_OUTPUT_SETBIT | (8u << 4) | 8u)  /* D7 = PI8 */
63	#define IRON_GPIO_SO     ((4u << 4) | 6u)               /* D6 = PE6 input */
64	#define IRON_GPIO_HEAT   (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
65	                          (0u << 4) | 6u)              /* D3 = PA6  */
66	#define IRON_GPIO_SLEEP  (GPIO_PULLUP | (6u << 4) | 3u) /* D2 = PG3, active low */
67	
68	/* --- Timing (us) --- */
69	#define IRON_SPI_HALF_PERIOD_US  2    /* ~250kHz bit clock */
70	#define IRON_TICK_MS             100  /* PID period */
71	
72	/* --- PID limits --- */
73	#define IRON_TEMP_MIN     100
74	#define IRON_TEMP_MAX     480
75	#define IRON_TEMP_CUTOFF  500
76	#define IRON_PWR_MAX      100.0f
77	#define IRON_PID_DT       (IRON_TICK_MS / 1000.0f)
78	#define IRON_PID_KP_MAX   20.0f
79	#define IRON_PID_KI_MAX   2.0f
80	#define IRON_PID_KD_MAX   20.0f
81	#define IRON_SAMPLE_MAX_AGE  0.6f
82	
83	/* Software PWM: the iron module ticks every 100ms; the PWM cycle spans
84	 * IRON_PWM_TICKS ticks => 2s period (0.5Hz). Soldering irons have large
85	 * thermal inertia, so this is far below their thermal time constant and the
86	 * resulting ripple is negligible.  power% => the heater stays ON for the
87	 * first N slices of each cycle, OFF for the rest.
88	 *
89	 * 20 slices give 5% resolution.  That matters because an idling JBC245 only
90	 * needs roughly 6-18% duty to hold temperature, so a coarser scale would
91	 * quantise the entire operating point away: at 10 slices everything below
92	 * 9% collapsed to "off" and 10-19% all became 10%, which made the tip hunt
93	 * around its target instead of settling. */
94	#define IRON_PWM_TICKS       20   /* 2s cycle = 20 x 100ms slices */
95	
96	/* Derivative low-pass: the temperature is sampled every 300ms, which makes
97	 * the raw difference quotient noisy and would kick the D-term hard on every
98	 * sample.  Clamp the measured rate of change instead; the units are C/s, so
99	 * with the default Kd the D-term is bounded to 1.5 * 8 = 12% of output. */
100	#define IRON_D_MAX_SLOPE     8.0f   /* max temperature slope, C/s */
101	
102	/* JBC245 sleep detection (Arduino D2 = PG3, active low with pull-up).
103	 * Parking the handle simply stops the heater, so there is no staged
104	 * cool-down or standby temperature to wait for. */
105	#define IRON_SLEEP_DEBOUNCE_TICKS 3   /* 300ms bounce filter */
106	
107	/****************************************************************************
108	 * Private Data
109	 ****************************************************************************/
110	
111	static float g_temp_c      = 25.0f;
112	static int   g_target_c    = 350;
113	static bool  g_heating     = false;
114	static bool  g_sensor_ok   = false;
115	static float g_kp          = 3.0f;
116	static float g_ki          = 0.05f;
117	static float g_kd          = 1.5f;
118	static float g_power       = 0.0f;   /* 0..100 */
119	
120	/* PID state */
121	static float g_integral    = 0.0f;
122	static float g_last_temp_c = 25.0f;
123	static bool  g_have_sample = false;
124	static float g_sample_age  = 0.0f;
125	
126	/* Software PWM state: counts down every tick */
127	static int   g_pwm_slice   = 0;
128	
129	/* JBC245 sleep state: true while the handle rests in its stand, signalled
130	 * by the SLEEP line being pulled low. */
131	
132	static bool  g_sleep_pin_deb   = false;
133	static int   g_sleep_deb_cnt   = 0;
134	static bool  g_parked          = false;
135	static int   g_target_eff_c    = 350;
136	
137	/****************************************************************************
138	 * Private Functions
139	 ****************************************************************************/
140	
141	/****************************************************************************
142	 * Name: iron_spi_delay
143	 ****************************************************************************/
144	
145	static inline void iron_spi_delay(void)
146	{
147	  up_udelay(IRON_SPI_HALF_PERIOD_US);
148	}
149	
150	/****************************************************************************
151	 * Name: max6675_read
152	 *
153	 * Bit-bang a 16-bit read from the MAX6675.
154	 * Returns 16-bit raw value (D2 = thermocouple open flag).
155	 ****************************************************************************/
156	
157	static uint16_t max6675_read(void)
158	{
159	  uint16_t value = 0;
160	  int i;
161	
162	  /* CS low to start */
163	  stm32_gpiowrite(IRON_GPIO_CS, false);
164	  iron_spi_delay();
165	
166	  /* Read 16 bits MSB first.  The MAX6675 updates SO after the falling
167	   * edge; sample each bit while SCK is low and stable. */
168	  for (i = 0; i < 16; i++)
169	    {
170	      /* SCK low -> data valid to read */
171	      stm32_gpiowrite(IRON_GPIO_SCK, false);
172	      iron_spi_delay();
173	
174	      /* Sample SO while SCK is low: the MAX6675 shifts out the next bit on
175	       * the falling edge, so the line is already stable when the clock is
176	       * low and we read before driving it high again. */
177	      value = (value << 1);
178	      if (stm32_gpioread(IRON_GPIO_SO))
179	        {
180	          value |= 1;
181	        }
182	
183	      /* SCK high */
184	      stm32_gpiowrite(IRON_GPIO_SCK, true);
185	      iron_spi_delay();
186	    }
187	
188	  /* CS high to end.  Leave SCK low: the MAX6675 advances SO on every falling
189	   * edge, so a clock left high would turn the first write of the next read
190	   * into a spurious edge and shift that whole frame one bit. */
191	
192	  stm32_gpiowrite(IRON_GPIO_CS, true);
193	  stm32_gpiowrite(IRON_GPIO_SCK, false);
194	  iron_spi_delay();
195	
196	  return value;
197	}
198	
199	/****************************************************************************
200	 * Name: max6675_temp
201	 *
202	 * Decode a 16-bit MAX6675 frame into Celsius.
203	 * Returns false (no temperature written) when the thermocouple is open,
204	 * shorted, or the frame is otherwise unusable.
205	 ****************************************************************************/
206	
207	static bool max6675_temp(uint16_t raw, FAR float *temp_c)
208	{
209	  uint16_t code;
210	
211	  if (temp_c == NULL || (raw & 0x8000) != 0 || (raw & 0x0002) != 0 ||
212	      (raw & 0x0004) != 0)
213	    {
214	      return false;
215	    }
216	
217	  code = (raw >> 3) & 0x0fff;
218	  *temp_c = (float)code * 0.25f;
219	  return *temp_c >= 0.0f && *temp_c <= 1023.75f;
220	}
221	
222	/****************************************************************************
223	 * Name: iron_pid_update
224	 *
225	 * Compute heater power % from PID on temperature error.
226	 ****************************************************************************/
227	
228	static void iron_pid_update(float dt)
229	{
230	  float error;
231	  float p_term;
232	  float i_term;
233	  float d_term;
234	  float d_slope;
235	  float candidate;
236	
237	  if (!g_heating || !g_sensor_ok || !g_have_sample)
238	    {
239	      g_power = 0.0f;
240	      g_integral = 0.0f;
241	      return;
242	    }
243	
244	  error = (float)g_target_eff_c - g_temp_c;
245	  p_term = g_kp * error;
246	  d_slope = (g_temp_c - g_last_temp_c) / dt;
247	  if (d_slope > IRON_D_MAX_SLOPE) d_slope = IRON_D_MAX_SLOPE;
248	  if (d_slope < -IRON_D_MAX_SLOPE) d_slope = -IRON_D_MAX_SLOPE;
249	  d_term = -g_kd * d_slope;
250	
251	  /* Conditional integration: do not integrate farther into saturation. */
252	  candidate = p_term + g_ki * g_integral + d_term;
253	  if (!((candidate >= IRON_PWR_MAX && error > 0.0f) ||
254	        (candidate <= 0.0f && error < 0.0f)))
255	    {
256	      g_integral += error * dt;
257	      if (g_integral > 1000.0f) g_integral = 1000.0f;
258	      if (g_integral < -1000.0f) g_integral = -1000.0f;
259	    }
260	
261	  i_term = g_ki * g_integral;
262	  g_power = p_term + i_term + d_term;
263	  if (g_power < 0.0f) g_power = 0.0f;
264	  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
265	}
266	
267	/****************************************************************************
268	 * Name: iron_pwm_apply
269	 *
270	 * Software PWM: turn heater GPIO on/off based on power %.
271	 * Called once per tick (100ms).  Each tick advances one slice of the
272	 * IRON_PWM_TICKS-long cycle; the heater is on for the first on_slices of
273	 * them, so the duty cycle is on_slices / IRON_PWM_TICKS.
274	 ****************************************************************************/
275	
276	static void iron_pwm_apply(void)
277	{
278	  /* Round rather than truncate: a floor here would bias every duty cycle
279	   * downwards by up to one full slice. */
280	
281	  int on_slices = (int)(g_power / 100.0f * IRON_PWM_TICKS + 0.5f);
282	
283	  if (!g_heating || on_slices <= 0)
284	    {
285	      g_pwm_slice = 0;
286	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
287	      return;
288	    }
289	
290	  if (on_slices >= IRON_PWM_TICKS)
291	    {
292	      /* Constant on: restart the phase so a later drop back to a partial
293	       * duty cycle starts from a clean slice rather than a stale one. */
294	
295	      g_pwm_slice = 0;
296	      stm32_gpiowrite(IRON_GPIO_HEAT, true);
297	      return;
298	    }
299	
300	  stm32_gpiowrite(IRON_GPIO_HEAT, g_pwm_slice < on_slices);
301	  g_pwm_slice++;
302	  if (g_pwm_slice >= IRON_PWM_TICKS)
303	    {
304	      g_pwm_slice = 0;
305	    }
306	}
307	
308	/****************************************************************************
309	 * Name: iron_sleep_tick
310	 *
311	 * Debounce the JBC245 SLEEP pin.  The handle pulls the line low while the
312	 * iron rests in its stand, so an active-low reading means "parked".
313	 *
314	 * Parked irons do not heat at all: the heater is held off for as long as
315	 * the pin reads low, and the PID state is cleared so that picking the iron
316	 * back up starts from a clean controller rather than from whatever the
317	 * integrator had accumulated before it was put down.
318	 ****************************************************************************/
319	
320	static void iron_sleep_tick(void)
321	{
322	  bool raw;
323	
324	  raw = !stm32_gpioread(IRON_GPIO_SLEEP);   /* active low: in stand */
325	
326	  /* Bounce filter: require N consecutive identical samples. */
327	  if (raw != g_sleep_pin_deb)
328	    {
329	      g_sleep_deb_cnt++;
330	      if (g_sleep_deb_cnt >= IRON_SLEEP_DEBOUNCE_TICKS)
331	        {
332	          g_sleep_pin_deb = raw;
333	          g_sleep_deb_cnt = 0;
334	        }
335	    }
336	  else
337	    {
338	      g_sleep_deb_cnt = 0;
339	    }
340	
341	  if (g_sleep_pin_deb == g_parked)
342	    {
343	      return;   /* no transition */
344	    }
345	
346	  if (g_sleep_pin_deb)
347	    {
348	      /* Just parked: stop heating and drop the PID history. */
349	      g_parked = true;
350	      g_power       = 0.0f;
351	      g_integral    = 0.0f;
352	      g_pwm_slice   = 0;
353	      g_last_temp_c = g_temp_c;
354	      g_target_eff_c = g_target_c;
355	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
356	      syslog(LOG_INFO, "IRON: parked, heater off\n");
357	    }
358	  else
359	    {
360	      /* Picked back up: resume the user target with a clean controller. */
361	      g_parked = false;
362	      g_integral    = 0.0f;
363	      g_last_temp_c = g_temp_c;
364	      g_target_eff_c = g_target_c;
365	      syslog(LOG_INFO, "IRON: picked up, resuming %dC\n", g_target_c);
366	    }
367	}
368	
369	/* Returns true while the iron is parked in its stand (SLEEP line low). */
370	
371	static bool iron_is_parked(void)
372	{
373	  return g_parked;
374	}
375	
376	
377	int iron_init(void)
378	{
379	  /* Configure GPIO pins */
380	  stm32_configgpio(IRON_GPIO_SCK);
381	  stm32_configgpio(IRON_GPIO_CS);
382	  stm32_configgpio(IRON_GPIO_SO);
383	  stm32_configgpio(IRON_GPIO_HEAT);
384	  stm32_configgpio(IRON_GPIO_SLEEP);
385	
386	  /* Idle states: CS high, clock low, heater off */
387	  stm32_gpiowrite(IRON_GPIO_CS, true);
388	  stm32_gpiowrite(IRON_GPIO_SCK, false);
389	  stm32_gpiowrite(IRON_GPIO_HEAT, false);
390	
391	  /* Probe MAX6675 */
392	  {
393	    uint16_t raw = max6675_read();
394	    float t;
395	
396	    if (!max6675_temp(raw, &t))
397	      {
398	        syslog(LOG_WARNING, "IRON: invalid MAX6675 frame (raw=0x%04x)\n", raw);
399	        g_sensor_ok = false;
400	      }
401	    else
402	      {
403	        g_temp_c = t;
404	        g_last_temp_c = t;
405	        g_have_sample = true;
406	        g_sample_age = 0.0f;
407	        g_sensor_ok = true;
408	        syslog(LOG_INFO, "IRON: MAX6675 ok, T=%.1fC (raw=0x%04x)\n", t, raw);
409	      }
410	  }
411	
412	  return 0;
413	}
414	
415	void iron_tick(void)
416	{
417	  static int read_div = 0;
418	  uint16_t raw;
419	  float t;
420	  bool fresh_sample = false;
421	
422	  g_sample_age += IRON_PID_DT;
423	
424	  /* JBC245 sleep detection runs every tick, before sampling. */
425	  iron_sleep_tick();
426	
427	  /* CS high starts a conversion.  Read only after three 100ms ticks so the
428	   * MAX6675 has exceeded its 220ms maximum conversion time. */
429	  if (++read_div >= 3)
430	    {
431	      read_div = 0;
432	      raw = max6675_read();
433	
434	      if (max6675_temp(raw, &t))
435	        {
436	          if (t >= IRON_TEMP_CUTOFF)
437	            {
438	              syslog(LOG_WARNING, "IRON: over-temperature %.1fC\n", t);
439	              g_sensor_ok = false;
440	            }
441	          else
442	            {
443	              g_last_temp_c = g_temp_c;
444	              g_temp_c = t;
445	              g_sample_age = 0.0f;
446	              g_have_sample = true;
447	              g_sensor_ok = true;
448	              fresh_sample = true;
449	            }
450	        }
451	      else
452	        {
453	          syslog(LOG_WARNING, "IRON: invalid MAX6675 frame (raw=0x%04x)\n", raw);
454	          g_sensor_ok = false;
455	        }
456	    }
457	
458	  if (!g_sensor_ok || g_sample_age > IRON_SAMPLE_MAX_AGE)
459	    {
460	      /* A stale or invalid sensor reading must always shut the heater off. */
461	      g_sensor_ok = false;
462	      g_power = 0.0f;
463	      g_integral = 0.0f;
464	      g_pwm_slice = 0;
465	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
466	      return;
467	    }
468	
469	  /* Parked in the stand: no heating at all, regardless of the target. */
470	
471	  if (iron_is_parked())
472	    {
473	      g_power = 0.0f;
474	      g_integral = 0.0f;
475	      g_pwm_slice = 0;
476	      g_last_temp_c = g_temp_c;
477	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
478	      return;
479	    }
480	
481	  if (fresh_sample)
482	    {
483	      iron_pid_update(IRON_PID_DT * 3.0f);
484	    }
485	
486	  iron_pwm_apply();
487	}
488	
489	void iron_set_target(int temp_c)
490	{
491	  if (temp_c < IRON_TEMP_MIN) temp_c = IRON_TEMP_MIN;
492	  if (temp_c > IRON_TEMP_MAX) temp_c = IRON_TEMP_MAX;
493	  if (temp_c != g_target_c)
494	    {
495	      g_integral = 0.0f;
496	      g_last_temp_c = g_temp_c;
497	    }
498	
499	  g_target_c = temp_c;
500	
501	  /* While parked the target is remembered but not acted on; the effective
502	   * target is restored when the iron is picked up again. */
503	
504	  if (!iron_is_parked())
505	    {
506	      g_target_eff_c = temp_c;
507	    }
508	}
509	
510	void iron_set_heater(bool on)
511	{
512	  g_heating = on;
513	  if (!on)
514	    {
515	      /* Stop the output and drop the controller history.  The park state is
516	       * deliberately left alone: it tracks the SLEEP pin, which only
517	       * iron_sleep_tick() reads.  Writing it here from a raw pin sample
518	       * would bypass the debounce and let a UI action overwrite a physical
519	       * condition -- turning the heat switch off and on again would then
520	       * latch "parked" without the iron having moved. */
521	
522	      g_integral = 0.0f;
523	      g_last_temp_c = g_temp_c;
524	      g_power = 0.0f;
525	      g_pwm_slice = 0;
526	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
527	    }
528	}
529	
530	void iron_set_pid(float p, float i, float d)
531	{
532	  if (!isfinite(p) || !isfinite(i) || !isfinite(d) || p < 0.0f ||
533	      i < 0.0f || d < 0.0f || p > IRON_PID_KP_MAX ||
534	      i > IRON_PID_KI_MAX || d > IRON_PID_KD_MAX)
535	    {
536	      syslog(LOG_WARNING, "IRON: rejected invalid PID P=%.2f I=%.2f D=%.2f\n", p, i, d);
537	      return;
538	    }
539	
540	  if (p != g_kp || i != g_ki || d != g_kd)
541	    {
542	      g_integral = 0.0f;
543	      g_last_temp_c = g_temp_c;
544	    }
545	
546	  g_kp = p;
547	  g_ki = i;
548	  g_kd = d;
549	}
550	
551	void iron_get_status(FAR struct iron_status_s *st)
552	{
553	  if (st == NULL)
554	    {
555	      return;
556	    }
557	
558	  st->temp_c       = (int)g_temp_c;
559	  st->target_c     = g_target_c;
560	  st->power_pct    = g_power;
561	  st->heating      = g_heating;
562	  st->sensor_ok    = g_sensor_ok;
563	  st->sleep_active = g_parked;
564	  st->target_eff_c = g_target_eff_c;
565	}
