1	/****************************************************************************
2	 * Contest 2026 team 008 - charging station main
3	 *
4	 * Entry point: initializes LVGL, display and touchscreen, then
5	 * enters the LVGL event loop with the charging station UI.
6	 * Reads the SW3538 chargers and INA226 monitors over the software I2C
7	 * bus (D4/D5) every ~500ms.
8	 ****************************************************************************/
9	
10	#include <nuttx/config.h>
11	
12	#include <stdio.h>
13	#include <stdlib.h>
14	#include <string.h>
15	#include <syslog.h>
16	#include <unistd.h>
17	
18	#include <lvgl/lvgl.h>
19	
20	#include "charging_station_ui.h"
21	#include "cs_i2c_sw.h"
22	#include "sw3538.h"
23	#include "ina226.h"
24	#include "iron.h"
25	
26	/****************************************************************************
27	 * Pre-processor Definitions
28	 ****************************************************************************/
29	
30	#define INA226_RETRY_TICKS  50   /* 50 x 100ms = 5s between re-probes */
31	#define SW3538_RETRY_TICKS  50   /* 50 x 100ms = 5s between hot-plug probes */
32	#define SW3538_FAIL_LIMIT   5    /* sweeps failed before a channel is dropped */
33	
34	/****************************************************************************
35	 * Private Data
36	 ****************************************************************************/
37	
38	static bool g_sw3538_ok[4];
39	
40	/* Consecutive read failures per channel.  A module that is unplugged falls
41	 * back to the slow presence probe instead of failing on every sweep. */
42	
43	static uint8_t g_sw3538_fail[4];
44	
45	/* Channel read by the next tick; the four SW3538 modules are polled in
46	 * rotation so no single tick carries the whole bus sweep. */
47	
48	static int  g_poll_chan;
49	
50	/****************************************************************************
51	 * Private Functions
52	 ****************************************************************************/
53	
54	/****************************************************************************
55	 * Name: sw3538_poll_channel
56	 *
57	 * Read one SW3538 and push its data into the matching UI channel card.
58	 * On failure, mark the channel idle but keep the app running.
59	 *
60	 * One channel takes about 23ms (four ADC conversions, each waiting 5ms for
61	 * the chip to latch a result), so the four channels are spread across four
62	 * consecutive ticks rather than read back to back.  A full sweep still
63	 * completes every 400ms, but no single tick blocks the LVGL loop and the
64	 * touch input timer for ~92ms.
65	 ****************************************************************************/
66	
67	static void sw3538_poll_channel(int channel)
68	{
69	  struct sw3538_status_s st;
70	  int ret;
71	
72	  if (!g_sw3538_ok[channel])
73	    {
74	      return;
75	    }
76	
77	  ret = sw3538_read_status_channel(channel, &st);
78	  if (ret < 0)
79	    {
80	      cs_ui_set_channel_online(channel, false, false);
81	
82	      /* Drop a module that has stopped answering back to the slow presence
83	       * probe, so a card that was unplugged does not log a failure on every
84	       * sweep and can be picked up again when it is plugged back in. */
85	
86	      if (++g_sw3538_fail[channel] >= SW3538_FAIL_LIMIT)
87	        {
88	          g_sw3538_fail[channel] = 0;
89	          g_sw3538_ok[channel] = false;
90	          syslog(LOG_WARNING, "Charging Station: SW3538 CH%d lost\n",
91	                 channel + 1);
92	        }
93	
94	      return;
95	    }
96	
97	  g_sw3538_fail[channel] = 0;
98	
99	  cs_ui_set_channel_ports(channel, (float)st.vout_mv / 1000.0f,
100	                          (float)st.ic_ma / 1000.0f,
101	                          (float)st.vout_mv / 1000.0f,
102	                          (float)st.ia_ma / 1000.0f,
103	                          sw3538_proto_name(st.proto), st.temp_c,
104	                          st.temp_valid);
105	  cs_ui_set_channel_online(channel, (st.online & 0x02) != 0,
106	                           (st.online & 0x01) != 0);
107	
108	  syslog(LOG_INFO, "SW3538 CH%d: Vout=%dmV Ic=%dmA Ia=%dmA "
109	         "temp=%s%dC proto=%d(%s)\n", channel + 1, st.vout_mv,
110	         st.ic_ma, st.ia_ma, st.temp_valid ? "" : "N/A ", st.temp_c,
111	         st.proto, sw3538_proto_name(st.proto));
112	}
113	
114	/****************************************************************************
115	 * Name: sw3538_retry_absent
116	 *
117	 * Presence-probe every channel that is not currently up, so a module plugged
118	 * in after boot is picked up without a reset.  Channel 3 is the one that
119	 * matters in practice: its card sits over the RJ45 jack, so it is left out
120	 * unless Ethernet is unused, and it may be fitted later while running.
121	 ****************************************************************************/
122	
123	static void sw3538_retry_absent(void)
124	{
125	  int channel;
126	
127	  for (channel = 0; channel < 4; channel++)
128	    {
129	      if (g_sw3538_ok[channel])
130	        {
131	          continue;
132	        }
133	
134	      if (sw3538_probe_channel(channel) == OK)
135	        {
136	          g_sw3538_ok[channel] = true;
137	          g_sw3538_fail[channel] = 0;
138	          syslog(LOG_INFO, "Charging Station: SW3538 CH%d detected "
139	                 "(hot-plug)\n", channel + 1);
140	        }
141	    }
142	}
143	
144	/****************************************************************************
145	 * Name: ina226_poll
146	 *
147	 * Read the total input monitor and the soldering iron monitor.
148	 *
149	 * The iron heater is switched by a 0.5 Hz software PWM (2s cycle), so a
150	 * single 35ms conversion window lands either fully on or fully off; the
151	 * value is a snapshot rather than an average, and a single low sample is
152	 * not a fault.
153	 ****************************************************************************/
154	
155	static void ina226_poll(void)
156	{
157	  struct ina226_sample_s s;
158	
159	  if (cs_ina226_read(CS_INA226_TOTAL, &s) == OK)
160	    {
161	      cs_ui_set_input_power((float)s.bus_mv / 1000.0f,
162	                            (float)s.current_ma / 1000.0f,
163	                            (float)s.power_mw / 1000.0f, true);
164	
165	      syslog(LOG_INFO, "INA226 IN : %lumV %ldmA %lumW\n",
166	             (unsigned long)s.bus_mv, (long)s.current_ma,
167	             (unsigned long)s.power_mw);
168	    }
169	  else
170	    {
171	      cs_ui_set_input_power(0.0f, 0.0f, 0.0f, false);
172	    }
173	
174	  if (cs_ina226_read(CS_INA226_IRON, &s) == OK)
175	    {
176	      cs_ui_set_iron_power((float)s.bus_mv / 1000.0f,
177	                           (float)s.current_ma / 1000.0f,
178	                           (float)s.power_mw / 1000.0f, true);
179	
180	      syslog(LOG_INFO, "INA226 IRON: %lumV %ldmA %lumW\n",
181	             (unsigned long)s.bus_mv, (long)s.current_ma,
182	             (unsigned long)s.power_mw);
183	    }
184	  else
185	    {
186	      cs_ui_set_iron_power(0.0f, 0.0f, 0.0f, false);
187	    }
188	}
189	
190	/****************************************************************************
191	 * Name: data_timer_cb
192	 *
193	 * Periodically refresh simulated data + real SW3538 readings.
194	 ****************************************************************************/
195	
196	static void data_timer_cb(lv_timer_t *timer)
197	{
198	  static int slow = 0;
199	  static int retry = 0;
200	  struct iron_status_s ist;
201	
202	  cs_ui_data_tick();
203	
204	  /* Sync UI intent (target temp / heater on / PID) into the iron module */
205	  float kp;
206	  float ki;
207	  float kd;
208	
209	  iron_set_target(cs_ui_get_iron_target());
210	  iron_set_heater(cs_ui_get_iron_on());
211	  cs_ui_get_iron_pid(&kp, &ki, &kd);
212	  iron_set_pid(kp * 0.2f, ki * 0.4f, kd * 0.2f);
213	
214	  /* Soldering iron: PID tick every 100ms */
215	  iron_tick();
216	  iron_get_status(&ist);
217	  cs_ui_set_iron_real(ist.temp_c, ist.power_pct, ist.heating, ist.sensor_ok);
218	  cs_ui_set_iron_sleep(ist.sleep_active,
219	                       (ist.sleep_active ? ist.target_eff_c : ist.target_c));
220	
221	  /* SW3538 sweep: one channel per 100ms tick, so the bus work never blocks
222	   * the LVGL loop for longer than a single channel (~23ms). */
223	  sw3538_poll_channel(g_poll_chan);
224	  if (++g_poll_chan >= 4)
225	    {
226	      g_poll_chan = 0;
227	    }
228	
229	  /* INA226 is cheap (about 2ms for both monitors). */
230	  if (++slow >= 5)
231	    {
232	      slow = 0;
233	      ina226_poll();
234	    }
235	
236	  /* Re-probe devices that were absent at boot: the power monitors, and any
237	   * SW3538 module that has been plugged in since. */
238	  if (++retry >= INA226_RETRY_TICKS)
239	    {
240	      retry = 0;
241	      cs_ina226_retry();
242	      sw3538_retry_absent();
243	    }
244	
245	  (void)timer;
246	}
247	
248	/****************************************************************************
249	 * Name: lv_nuttx_loop
250	 *
251	 * Standard LVGL poll loop.
252	 ****************************************************************************/
253	
254	static void lv_nuttx_loop(void)
255	{
256	  while (1)
257	    {
258	      uint32_t idle;
259	
260	      idle = lv_timer_handler();
261	      idle = idle ? idle : 1;
262	      usleep(idle * 1000);
263	    }
264	}
265	
266	/****************************************************************************
267	 * Public Functions
268	 ****************************************************************************/
269	
270	int main(int argc, FAR char *argv[])
271	{
272	  lv_nuttx_dsc_t info;
273	  lv_nuttx_result_t result;
274	
275	  syslog(LOG_INFO, "Charging Station starting\n");
276	
277	  /* Init soldering iron GPIO + MAX6675 probe (non-fatal) */
278	  iron_init();
279	
280	  /* Bring up the software I2C bus and probe the TCA9548A plus the four
281	   * SW3538 modules.  Every step is non-fatal: the UI must still come up
282	   * with no hardware attached. */
283	  if (sw3538_init() < 0)
284	    {
285	      syslog(LOG_WARNING, "Charging Station: TCA9548A not detected\n");
286	    }
287	  else
288	    {
289	      int channel;
290	
291	      for (channel = 0; channel < 4; channel++)
292	        {
293	          struct sw3538_status_s st;
294	
295	          if (sw3538_read_status_channel(channel, &st) == OK)
296	            {
297	              g_sw3538_ok[channel] = true;
298	              syslog(LOG_INFO, "Charging Station: SW3538 CH%d ready\n",
299	                     channel + 1);
300	            }
301	          else
302	            {
303	              syslog(LOG_WARNING, "Charging Station: SW3538 CH%d absent\n",
304	                     channel + 1);
305	            }
306	        }
307	    }
308	
309	  /* Probe the two INA226 power monitors on TCA channels 4 and 5. */
310	
311	  if (cs_ina226_init() < 0)
312	    {
313	      syslog(LOG_WARNING, "Charging Station: INA226 init failed\n");
314	    }
315	
316	  lv_init();
317	
318	  lv_nuttx_dsc_init(&info);
319	
320	#ifdef CONFIG_LV_USE_NUTTX_LCD
321	  info.fb_path = "/dev/lcd0";
322	#endif
323	
324	  lv_nuttx_init(&info, &result);
325	
326	  if (result.disp == NULL)
327	    {
328	      syslog(LOG_ERR, "Charging Station: display init failed\n");
329	      lv_deinit();
330	      return -1;
331	    }
332	
333	  /* Build the charging station UI */
334	  if (cs_ui_init(lv_screen_active()) < 0)
335	    {
336	      syslog(LOG_ERR, "Charging Station: UI init failed\n");
337	      lv_nuttx_deinit(&result);
338	      lv_deinit();
339	      return -1;
340	    }
341	
342	  /* Start data simulation timer (100ms) */
343	  lv_timer_create(data_timer_cb, 100, NULL);
344	
345	  syslog(LOG_INFO, "Charging Station: display res=%ldx%ld\n",
346	         (long)lv_display_get_horizontal_resolution(result.disp),
347	         (long)lv_display_get_vertical_resolution(result.disp));
348	
349	  if (result.indev)
350	    {
351	      /* Speed up touch reading: 20ms poll period (faster response) */
352	      lv_indev_set_mode(result.indev, LV_INDEV_MODE_TIMER);
353	      lv_timer_t *t = lv_indev_get_read_timer(result.indev);
354	      if (t)
355	        {
356	          lv_timer_set_period(t, 20);
357	        }
358	      syslog(LOG_INFO, "Charging Station: touchscreen registered (20ms poll)\n");
359	    }
360	  else
361	    {
362	      syslog(LOG_WARNING, "Charging Station: no touchscreen (indev NULL)\n");
363	    }
364	
365	  /* Enter the LVGL event loop */
366	  syslog(LOG_INFO, "Charging Station: entering poll loop\n");
367	  lv_nuttx_loop();
368	
369	  lv_nuttx_deinit(&result);
370	  lv_deinit();
371	  return 0;
372	}
