1	/****************************************************************************
2	 * Contest 2026 team 008 - SW3538 fast-charge chip driver (NuttX)
3	 *
4	 * Four SW3538 devices share I2C address 0x3c behind a TCA9548A at 0x70.
5	 * Each transaction selects exactly one TCA downstream channel first.
6	 *
7	 * The multiplexer hangs off the software I2C bus (see cs_i2c_sw.c), so it
8	 * does not share I2C4 with the FT5x06 touchscreen.  All bus access goes
9	 * through cs_i2c_transfer(), which re-selects the channel on every call and
10	 * holds a lock across select + transfer.
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	
15	#include <stdint.h>
16	#include <string.h>
17	#include <errno.h>
18	#include <syslog.h>
19	
20	#include <nuttx/i2c/i2c_master.h>
21	#include <nuttx/arch.h>
22	#include <arch/board/board.h>
23	
24	#include "cs_i2c_sw.h"
25	#include "sw3538.h"
26	
27	/****************************************************************************
28	 * Pre-processor Definitions
29	 ****************************************************************************/
30	
31	#define SW3538_ADDR              0x3c
32	#define SW3538_CHANNEL_COUNT     4
33	
34	#define SW3538_REG_PROTO         0x09
35	#define SW3538_REG_ONLINE        0x0d
36	#define SW3538_REG_I2C_EN        0x10
37	#define SW3538_REG_ADC_SEL       0x40
38	#define SW3538_REG_ADC_LO        0x41
39	#define SW3538_REG_ADC_HI        0x42
40	#define SW3538_REG_NTC_CURRENT   0x44
41	
42	/* Reg0x40 channel codes (register list, section 2.23).
43	 *
44	 * Channels 1 and 2 are the two output paths of the chip.  Register list
45	 * 2.8 (Reg0x0A) and 2.9 (Reg0x0D) both state that for the A+C mode used
46	 * here, path 1 is the Type-C port and path 2 is the Type-A port.
47	 */
48	
49	#define ADC_CH_PATH1             1   /* Type-C port current, 2.5mA/bit@5mohm */
50	#define ADC_CH_PATH2             2   /* Type-A port current, 2.5mA/bit@5mohm */
51	#define ADC_CH_VOUT              5   /* Output voltage, 6mV/bit */
52	#define ADC_CH_VIN               6   /* Input voltage, 10mV/bit (ADC off by default) */
53	#define ADC_CH_NTC               7   /* NTC voltage, 1.2mV/bit */
54	#define ADC_CH_VOUT_CONV        11   /* Converted output voltage, 1mV/bit */
55	
56	#define NTC_UV_PER_BIT           1200u
57	#define NTC_CURRENT_LOW_UA       20u
58	#define NTC_CURRENT_HIGH_UA      40u
59	
60	/****************************************************************************
61	 * Private Data
62	 ****************************************************************************/
63	
64	/* 104AT 100K NTC nominal resistance table.  The values must be calibrated
65	 * against the actual module at room temperature before they are relied upon
66	 * for thermal decisions.  This driver reports invalid data rather than a
67	 * fabricated temperature for values outside the supported table. */
68	
69	struct ntc_point_s
70	{
71	  int16_t temp_c;
72	  uint32_t resistance_ohm;
73	};
74	
75	static const struct ntc_point_s g_ntc_104at[] =
76	{
77	  {  0, 355000 }, { 10, 202000 }, { 20, 125000 }, { 25, 100000 },
78	  { 30,  80500 }, { 40,  51000 }, { 50,  33500 }, { 60,  22400 },
79	  { 70,  15300 }, { 80,  10600 }, { 90,   7400 }, {100,   5250 },
80	  {110,   3800 }, {120,   2800 },
81	};
82	
83	/****************************************************************************
84	 * Private Functions
85	 ****************************************************************************/
86	
87	static int sw3538_read_regs(uint8_t channel, uint8_t reg, uint8_t *buf,
88	                            int len)
89	{
90	  struct i2c_msg_s msg[2];
91	  uint8_t regaddr = reg;
92	
93	  msg[0].frequency = CS_I2C_FREQ;
94	  msg[0].addr = SW3538_ADDR;
95	  msg[0].flags = 0;
96	  msg[0].buffer = &regaddr;
97	  msg[0].length = 1;
98	
99	  msg[1].frequency = CS_I2C_FREQ;
100	  msg[1].addr = SW3538_ADDR;
101	  msg[1].flags = I2C_M_READ;
102	  msg[1].buffer = buf;
103	  msg[1].length = len;
104	
105	  return cs_i2c_transfer(channel, msg, 2);
106	}
107	
108	static int sw3538_write_reg(uint8_t channel, uint8_t reg, uint8_t val)
109	{
110	  struct i2c_msg_s msg;
111	  uint8_t tx[2] = { reg, val };
112	
113	  msg.frequency = CS_I2C_FREQ;
114	  msg.addr = SW3538_ADDR;
115	  msg.flags = 0;
116	  msg.buffer = tx;
117	  msg.length = sizeof(tx);
118	  return cs_i2c_transfer(channel, &msg, 1);
119	}
120	
121	/****************************************************************************
122	 * Name: sw3538_unlock
123	 *
124	 * Enable I2C writes on one chip.  Register list 2.10 (Reg0x10, bits 7-5)
125	 * requires the sequence 0x20 -> 0x40 -> 0x80 before any other register may
126	 * be written to; reads need no unlock.  Every SW3538 sits behind its own
127	 * multiplexer channel, so the sequence has to be replayed on whichever
128	 * channel is about to be written, and it must precede every write to
129	 * Reg0x40 or the ADC channel change is silently ignored.
130	 ****************************************************************************/
131	
132	static int sw3538_unlock(uint8_t channel)
133	{
134	  static const uint8_t seq[3] = { 0x20, 0x40, 0x80 };
135	  int i;
136	  int ret;
137	
138	  for (i = 0; i < 3; i++)
139	    {
140	      ret = sw3538_write_reg(channel, SW3538_REG_I2C_EN, seq[i]);
141	      if (ret < 0)
142	        {
143	          return ret;
144	        }
145	    }
146	
147	  return OK;
148	}
149	
150	static int sw3538_adc_code(uint8_t channel, uint8_t adc, FAR uint16_t *code)
151	{
152	  uint8_t lo;
153	  uint8_t hi;
154	  int ret;
155	
156	  if (code == NULL)
157	    {
158	      return -EINVAL;
159	    }
160	
161	  ret = sw3538_write_reg(channel, SW3538_REG_ADC_SEL, adc);
162	  if (ret < 0)
163	    {
164	      return ret;
165	    }
166	
167	  up_udelay(5000);
168	
169	  ret = sw3538_read_regs(channel, SW3538_REG_ADC_LO, &lo, 1);
170	  if (ret < 0)
171	    {
172	      return ret;
173	    }
174	
175	  ret = sw3538_read_regs(channel, SW3538_REG_ADC_HI, &hi, 1);
176	  if (ret < 0)
177	    {
178	      return ret;
179	    }
180	
181	  *code = (uint16_t)(((uint16_t)(hi & 0x0f) << 8) | lo);
182	  return OK;
183	}
184	
185	static bool sw3538_ntc_to_temp(uint16_t code, uint8_t ntc_current,
186	                               FAR int16_t *temp_c)
187	{
188	  uint32_t current_ua;
189	  uint32_t resistance;
190	  unsigned int i;
191	
192	  if (code == 0 || temp_c == NULL)
193	    {
194	      return false;
195	    }
196	
197	  current_ua = (ntc_current & 0x80) ? NTC_CURRENT_HIGH_UA :
198	                                      NTC_CURRENT_LOW_UA;
199	  resistance = ((uint32_t)code * NTC_UV_PER_BIT) / current_ua;
200	
201	  if (resistance > g_ntc_104at[0].resistance_ohm ||
202	      resistance < g_ntc_104at[(sizeof(g_ntc_104at) /
203	                                 sizeof(g_ntc_104at[0])) - 1].resistance_ohm)
204	    {
205	      return false;
206	    }
207	
208	  for (i = 0; i < (sizeof(g_ntc_104at) / sizeof(g_ntc_104at[0])) - 1; i++)
209	    {
210	      const struct ntc_point_s *high = &g_ntc_104at[i];
211	      const struct ntc_point_s *low = &g_ntc_104at[i + 1];
212	
213	      if (resistance <= high->resistance_ohm &&
214	          resistance >= low->resistance_ohm)
215	        {
216	          uint32_t span = high->resistance_ohm - low->resistance_ohm;
217	          uint32_t offset = high->resistance_ohm - resistance;
218	
219	          *temp_c = (int16_t)(high->temp_c +
220	                    ((int32_t)offset * (low->temp_c - high->temp_c) / span));
221	          return true;
222	        }
223	    }
224	
225	  return false;
226	}
