231	
232	int sw3538_init(void)
233	{
234	  int ret;
235	
236	  ret = cs_i2c_bus_init();
237	  if (ret < 0)
238	    {
239	      syslog(LOG_ERR, "SW3538: software I2C bus init failed\n");
240	      return ret;
241	    }
242	
243	  ret = cs_i2c_mux_probe();
244	  if (ret < 0)
245	    {
246	      syslog(LOG_ERR, "SW3538: no TCA9548A ACK at 0x%02x\n", CS_TCA9548A_ADDR);
247	      return ret;
248	    }
249	
250	  syslog(LOG_INFO, "SW3538: TCA9548A ready at 0x%02x on software I2C\n",
251	         CS_TCA9548A_ADDR);
252	  return OK;
253	}
254	
255	int sw3538_read_status_channel(uint8_t channel,
256	                                FAR struct sw3538_status_s *st)
257	{
258	  uint16_t code;
259	  uint8_t proto;
260	  uint8_t online;
261	  uint8_t ntc_current;
262	  int ret;
263	
264	  if (st == NULL || channel >= SW3538_CHANNEL_COUNT)
265	    {
266	      return -EINVAL;
267	    }
268	
269	  memset(st, 0, sizeof(*st));
270	
271	  /* Reg0x40 is a write; the chip has to be write-enabled first or the ADC
272	   * channel selection does not take effect and every field would report the
273	   * same latched value. */
274	
275	  ret = sw3538_unlock(channel);
276	  if (ret < 0)
277	    {
278	      return ret;
279	    }
280	
281	  ret = sw3538_read_regs(channel, SW3538_REG_PROTO, &proto, 1);
282	  if (ret < 0)
283	    {
284	      return ret;
285	    }
286	
287	  ret = sw3538_read_regs(channel, SW3538_REG_ONLINE, &online, 1);
288	  if (ret < 0)
289	    {
290	      return ret;
291	    }
292	
293	  ret = sw3538_adc_code(channel, ADC_CH_VOUT, &code);
294	  if (ret < 0)
295	    {
296	      return ret;
297	    }
298	  st->vout_mv = (uint16_t)(code * 6u);
299	
300	  ret = sw3538_adc_code(channel, ADC_CH_PATH1, &code);
301	  if (ret < 0)
302	    {
303	      return ret;
304	    }
305	  st->ic_ma = (uint16_t)(code * 25u / 10u);
306	
307	  ret = sw3538_adc_code(channel, ADC_CH_PATH2, &code);
308	  if (ret < 0)
309	    {
310	      return ret;
311	    }
312	  st->ia_ma = (uint16_t)(code * 25u / 10u);
313	
314	  ret = sw3538_read_regs(channel, SW3538_REG_NTC_CURRENT, &ntc_current, 1);
315	  if (ret < 0)
316	    {
317	      return ret;
318	    }
319	
320	  ret = sw3538_adc_code(channel, ADC_CH_NTC, &code);
321	  if (ret < 0)
322	    {
323	      return ret;
324	    }
325	
326	  st->temp_valid = sw3538_ntc_to_temp(code, ntc_current, &st->temp_c);
327	  st->proto = proto & 0x0f;
328	  st->online = online & 0x03;
329	  return OK;
330	}
331	
332	int sw3538_read_status(FAR struct sw3538_status_s *st)
333	{
334	  return sw3538_read_status_channel(0, st);
335	}
