337	/****************************************************************************
338	 * Name: sw3538_probe_channel
339	 *
340	 * Cheap presence check on one multiplexer channel: write-enable the chip and
341	 * read back its protocol register.  Used to pick up a module that is plugged
342	 * in after boot, so it must not rely on any state left by an earlier read.
343	 ****************************************************************************/
344	
345	int sw3538_probe_channel(uint8_t channel)
346	{
347	  uint8_t proto;
348	
349	  if (channel >= SW3538_CHANNEL_COUNT)
350	    {
351	      return -EINVAL;
352	    }
353	
354	  if (sw3538_unlock(channel) < 0)
355	    {
356	      return -ENODEV;
357	    }
358	
359	  if (sw3538_read_regs(channel, SW3538_REG_PROTO, &proto, 1) < 0)
360	    {
361	      return -ENODEV;
362	    }
363	
364	  return OK;
365	}
366	
367	const char *sw3538_proto_name(uint8_t proto)
368	{
369	  switch (proto)
370	    {
371	      case 0:  return "IDLE";
372	      case 1:  return "QC2.0";
373	      case 2:  return "QC3.0";
374	      case 3:  return "QC3+";
375	      case 4:  return "FCP";
376	      case 5:  return "SCP";
377	      case 6:  return "PD";
378	      case 7:  return "PD-PPS";
379	      case 8:  return "PE1.1";
380	      case 9:  return "PE2.0";
381	      case 10: return "VOOC1";
382	      case 11: return "VOOC4";
383	      case 13: return "SFCP";
384	      case 14: return "AFC";
385	      case 15: return "TFCP";
386	      default: return "?";
387	    }
388	}
